const update = $json;
const message = update.message || update.edited_message || {};
const from = message.from || {};
const chat = message.chat || {};
const messageText = String(update.message_text || message.text || message.caption || '').trim();
const normalizedText = String(update.normalized_text || messageText.toLowerCase().replace(/\s+/g, ' ')).trim();

const claimPhrases = [
  'warranty claim',
  'raise claim',
  'replacement',
  'repair',
  'not working',
  'issue with',
  'problem with',
  'claim'
];

const isClaimIntent = claimPhrases.some((phrase) => normalizedText.includes(phrase));
const telegramUserId = update.telegram_user_id || update.user_id || from.id || '';

return [
  {
    json: {
      chat_id: update.chat_id || chat.id,
      telegram_user_id: telegramUserId,
      user_name: update.user_name || [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Telegram User',
      message_text: messageText,
      normalized_text: normalizedText,
      is_claim_intent: isClaimIntent
    }
  }
];

function normalize(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function productLabel(product) {
  const name = product.Product_Name || 'Unnamed product';
  const brand = product.Brand || 'Unknown brand';
  const status = product.Warranty_Status || 'Unknown';
  return `${name} - ${brand} - ${status}`;
}

function claimId() {
  return `claim_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

const intent = $node['Detect Claim Intent'].json;
const userId = String(intent.telegram_user_id || '').trim();
const messageText = intent.message_text || '';
const normalizedMessage = normalize(messageText);

const rows = $input.all().map((item) => item.json || {});
const userProducts = rows.filter((row) => String(row.User_ID || '').trim() === userId);

const triggerWords = [
  'warranty claim',
  'raise claim',
  'replacement',
  'repair',
  'not working',
  'issue with',
  'problem with',
  'claim',
  'warranty',
  'product',
  'please',
  'for',
  'my',
  'the',
  'a',
  'an'
];

let query = ` ${normalizedMessage} `;
for (const phrase of triggerWords) {
  query = query.replace(new RegExp(` ${normalize(phrase)} `, 'g'), ' ');
}
query = query.replace(/\s+/g, ' ').trim();

const queryTerms = query.split(' ').filter((term) => term.length >= 2);

function scoreProduct(product) {
  const name = normalize(product.Product_Name);
  const brand = normalize(product.Brand);
  const seller = normalize(product.Seller);
  const invoice = normalize(product.Invoice_Number);
  const haystack = [name, brand, seller, invoice].filter(Boolean).join(' ');
  let score = 0;

  if (name && normalizedMessage.includes(name)) score += 8;
  if (invoice && normalizedMessage.includes(invoice)) score += 8;
  if (brand && normalizedMessage.includes(brand)) score += 2;

  for (const term of queryTerms) {
    if (name.split(' ').includes(term)) score += 3;
    else if (haystack.includes(term)) score += 1;
  }

  return score;
}

const scored = userProducts
  .map((product) => ({ product, score: scoreProduct(product) }))
  .filter((entry) => entry.score > 0)
  .sort((a, b) => b.score - a.score);

let match_status = 'none';
let matchedProduct = null;
let replyText = '';
let shouldAppendClaim = false;

if (userProducts.length === 0) {
  replyText = 'No saved warranties found yet. Upload a bill or warranty card first.';
} else if (scored.length === 1) {
  match_status = 'single';
  matchedProduct = scored[0].product;
  shouldAppendClaim = true;
  replyText = [
    'I found this product:',
    '',
    `Product: ${matchedProduct.Product_Name || 'Unnamed product'}`,
    `Brand: ${matchedProduct.Brand || 'Not found'}`,
    `Warranty Valid Till: ${matchedProduct.Warranty_Expiry_Date || 'Unknown'}`,
    `Status: ${matchedProduct.Warranty_Status || 'Unknown'}`,
    `Support Email: ${matchedProduct.Support_Email || 'Not found'}`,
    '',
    'Please describe the issue in one sentence.',
    'Example: The product is not working properly.'
  ].join('\n');
} else if (scored.length > 1) {
  match_status = 'multiple';
  const options = scored.slice(0, 10).map((entry, index) => `${index + 1}. ${productLabel(entry.product)}`).join('\n');
  replyText = `I found multiple matching products:\n\n${options}\n\nPlease be more specific. Send: claim PRODUCT_NAME`;
} else {
  const products = userProducts.slice(0, 10).map((product, index) => `${index + 1}. ${productLabel(product)}`).join('\n');
  replyText = `I could not match that claim request to a saved product.\n\nYour saved products:\n${products}\n\nPlease send: claim PRODUCT_NAME`;
}

const generatedClaimId = shouldAppendClaim ? claimId() : '';

return [
  {
    json: {
      chat_id: intent.chat_id,
      user_id: userId,
      message_text: messageText,
      match_status,
      should_append_claim: shouldAppendClaim,
      reply_text: replyText,
      claim_id: generatedClaimId,
      product_id: matchedProduct?.Product_ID || '',
      product_name: matchedProduct?.Product_Name || '',
      brand: matchedProduct?.Brand || '',
      warranty_expiry_date: matchedProduct?.Warranty_Expiry_Date || '',
      warranty_status: matchedProduct?.Warranty_Status || '',
      support_email: matchedProduct?.Support_Email || ''
    }
  }
];
